CREATE FUNCTION public.payroll_work_preview(t uuid,y integer,m integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e record;terms jsonb;prior public.hr_payroll;d public.hr_payroll_work_drafts;first_day date:=make_date(y,m,1);last_day date:=(make_date(y,m,1)+interval '1 month -1 day')::date;basis text;rate numeric;basic numeric;hours numeric;ot numeric;npl numeric;missing jsonb;amounts jsonb;result jsonb:='[]';f text;source_rows jsonb;BEGIN
IF NOT public.payroll_manager(t,auth.uid()) OR y NOT BETWEEN 2000 AND 2200 OR m NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'Payroll manager and valid month required';END IF;IF EXISTS(SELECT 1 FROM public.hr_payroll WHERE tenant_id=t AND year=y AND month=m) THEN RETURN public.payroll_preview(t,y,m);END IF;
FOR e IN SELECT * FROM public.hr_employees x WHERE x.tenant_id=t AND x.hire_date<=last_day AND (x.end_date IS NULL AND x.status IN('active','on_leave') OR x.end_date>=first_day) AND public.people_person_access(t,x.id,auth.uid()) AND lower(trim(x.first_name||' '||x.last_name)) NOT IN ('assembly promoters','cleaner cleaner','kitchen dishwasher','runner foh') LOOP
terms:=public.people_terms_at(t,e.id,last_day);SELECT * INTO prior FROM public.hr_payroll WHERE tenant_id=t AND employee_id=e.id AND make_date(year,month,1)<first_day ORDER BY year DESC,month DESC LIMIT 1;basis:=COALESCE(terms->>'pay_basis',prior.preparation->>'pay_basis',CASE WHEN e.employment_type='full_time' THEN 'month' ELSE 'hour' END);rate:=NULLIF(terms->>'pay_amount','')::numeric;IF rate IS NULL AND prior.id IS NOT NULL THEN rate:=COALESCE(prior.actual_base_salary,prior.forecast_base_salary);END IF;
missing:='[]';IF rate IS NULL OR rate<=0 THEN missing:=missing||jsonb_build_array('Needs your answer: dated pay terms unclear');END IF;
SELECT COALESCE(sum(CASE WHEN s.shift_type='regular' AND (s.hours_confirmed_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.hr_work_confirmations c WHERE c.tenant_id=t AND c.employee_id=e.id AND s.shift_date BETWEEN c.period_start AND c.period_end AND c.status='confirmed' AND c.fingerprint=public.people_work_fingerprint(t,e.id,c.period_start,c.period_end)) OR ((date_trunc('week',s.shift_date)::date+9)::timestamp AT TIME ZONE 'Asia/Hong_Kong')<=now()) THEN greatest(0,extract(epoch from(s.end_time-s.start_time+CASE WHEN s.end_time<s.start_time THEN interval '24 hours' ELSE interval '0 hours' END))/3600-s.break_minutes/60.0) ELSE 0 END),0),COALESCE(sum(CASE WHEN z.settle='pay' AND z.amount>0 THEN z.amount ELSE 0 END),0),COALESCE(sum(CASE WHEN z.settle='pay' AND z.amount<0 THEN -z.amount ELSE 0 END),0) INTO hours,ot,npl FROM public.hr_shifts s LEFT JOIN public.hr_shift_settlements z ON z.shift_id=s.id AND z.source_updated_at=s.updated_at WHERE s.tenant_id=t AND s.employee_id=e.id AND s.shift_date BETWEEN first_day AND last_day AND s.status<>'cancelled';
IF basis='hour' AND hours=0 THEN missing:=missing||jsonb_build_array('Waiting for hours');END IF;
IF EXISTS(SELECT 1 FROM public.hr_shifts s LEFT JOIN public.hr_shift_settlements z ON z.shift_id=s.id WHERE s.tenant_id=t AND s.employee_id=e.id AND s.shift_date BETWEEN first_day AND last_day AND (z.source_updated_at IS DISTINCT FROM s.updated_at AND z.id IS NOT NULL OR z.employee_status='disputed' OR s.no_show AND z.id IS NULL)) THEN missing:=missing||jsonb_build_array('Needs your answer: unsettled or disputed shift');END IF;
IF EXISTS(SELECT 1 FROM public.hr_leave_requests r WHERE r.tenant_id=t AND r.employee_id=e.id AND r.status='approved' AND r.start_date<=last_day AND r.end_date>=first_day) OR EXISTS(SELECT 1 FROM public.hr_shifts s WHERE s.tenant_id=t AND s.employee_id=e.id AND s.shift_date BETWEEN first_day AND last_day AND s.shift_type IN ('AL','SL','SH','NPL') AND NOT EXISTS(SELECT 1 FROM public.hr_shift_settlements z WHERE z.shift_id=s.id)) THEN missing:=missing||jsonb_build_array('Needs your answer: leave pay eligibility and average wage');END IF;
basic:=CASE WHEN basis='hour' THEN COALESCE(rate,0)*hours ELSE COALESCE(rate,0) END;IF basis='month' AND (e.hire_date>first_day OR e.end_date BETWEEN first_day AND last_day) THEN missing:=missing||jsonb_build_array('Needs your answer: partial-month pay');END IF;
amounts:=jsonb_build_object('basic',round(basic,2),'al',0,'sh',0,'sick',0,'unpaid',-npl,'overtime',ot,'other',0);f:=md5(public.people_work_fingerprint(t,e.id,first_day,last_day)||terms::text||COALESCE(to_jsonb(prior)::text,''));SELECT * INTO d FROM public.hr_payroll_work_drafts WHERE tenant_id=t AND employee_id=e.id AND year=y AND month=m;
SELECT COALESCE(jsonb_agg(jsonb_build_object('id',s.id,'date',s.shift_date,'reason',z.reason,'settle',z.settle,'hours',z.hours,'amount',z.amount,'employee_status',z.employee_status,'note',z.note) ORDER BY s.shift_date),'[]') INTO source_rows FROM public.hr_shifts s LEFT JOIN public.hr_shift_settlements z ON z.shift_id=s.id AND z.source_updated_at=s.updated_at WHERE s.tenant_id=t AND s.employee_id=e.id AND s.shift_date BETWEEN first_day AND last_day;
result:=result||jsonb_build_array(jsonb_build_object('employee_id',e.id,'name',e.first_name||' '||e.last_name,'venue_id',e.venue_id,'year',y,'month',m,'amounts',CASE WHEN d.source_fingerprint=f THEN d.amounts ELSE amounts END,'baseline',amounts,'notes',COALESCE(d.notes,'{}'),'draft_revision',COALESCE(d.revision,0),'source_fingerprint',f,'preparation',jsonb_build_object('pay_basis',basis,'hours',hours,'missing',missing,'sources',source_rows,'draft_stale',d.id IS NOT NULL AND d.source_fingerprint<>f)));END LOOP;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.payroll_work_preview(uuid,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_work_preview(uuid,integer,integer) TO authenticated;
CREATE FUNCTION public.payroll_save_work_draft(t uuid,y integer,m integer,rows jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE base jsonb;r jsonb;b jsonb;v jsonb;k text;e uuid;d public.hr_payroll_work_drafts;BEGIN
IF NOT public.payroll_manager(t,auth.uid()) THEN RAISE EXCEPTION 'Payroll manager required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));IF EXISTS(SELECT 1 FROM public.hr_payroll WHERE tenant_id=t AND year=y AND month=m) OR EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status='approved') THEN RAISE EXCEPTION 'Saved payroll is read-only';END IF;IF make_date(y,m,1)<>date_trunc('month',now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Only the current due month can be drafted';END IF;base:=public.payroll_work_preview(t,y,m);
FOR r IN SELECT value FROM jsonb_array_elements(rows) LOOP e:=(r->>'employee_id')::uuid;SELECT value INTO b FROM jsonb_array_elements(base) WHERE value->>'employee_id'=e::text;IF b IS NULL OR b->>'source_fingerprint' IS DISTINCT FROM r->>'source_fingerprint' THEN RAISE EXCEPTION 'Work inputs changed; review again';END IF;
IF NOT public.people_owner(t,auth.uid()) AND NOT COALESCE((public.people_effective_settings(t,(b->>'venue_id')::uuid)->>'managers_change_pay')::boolean,false) AND r->'amounts' IS DISTINCT FROM b->'baseline' THEN RAISE EXCEPTION 'Manager pay changes are not allowed';END IF;
v:=r->'amounts';IF jsonb_typeof(v)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(v))<>7 THEN RAISE EXCEPTION 'Seven draft amounts required';END IF;FOREACH k IN ARRAY ARRAY['basic','al','sh','sick','unpaid','overtime','other'] LOOP IF v->>k IS NULL OR (v->>k)::numeric::text IN ('NaN','Infinity','-Infinity') OR abs((v->>k)::numeric)>10000000 OR k<>'other' AND k<>'unpaid' AND (v->>k)::numeric<0 OR k='unpaid' AND (v->>k)::numeric>0 THEN RAISE EXCEPTION 'Invalid amount %',k;END IF;END LOOP;
IF (v->>'other')::numeric<>0 AND length(trim(COALESCE(r->'notes'->>'other','')))=0 THEN RAISE EXCEPTION 'Name the Other payment or deduction';END IF;SELECT * INTO d FROM public.hr_payroll_work_drafts WHERE tenant_id=t AND employee_id=e AND year=y AND month=m FOR UPDATE;IF COALESCE(d.revision,0)<>COALESCE((r->>'draft_revision')::integer,0) THEN RAISE EXCEPTION 'Draft changed; reload';END IF;
INSERT INTO public.hr_payroll_work_drafts(tenant_id,year,month,employee_id,amounts,baseline,source_fingerprint,notes,changed_by) VALUES(t,y,m,e,v,b->'baseline',r->>'source_fingerprint',COALESCE(r->'notes','{}'),auth.uid()) ON CONFLICT(tenant_id,year,month,employee_id) DO UPDATE SET amounts=v,baseline=b->'baseline',source_fingerprint=r->>'source_fingerprint',notes=COALESCE(r->'notes','{}'),changed_by=auth.uid(),changed_at=now(),revision=hr_payroll_work_drafts.revision+1;END LOOP;END $$;
REVOKE ALL ON FUNCTION public.payroll_save_work_draft(uuid,integer,integer,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_save_work_draft(uuid,integer,integer,jsonb) TO authenticated;
COMMENT ON TABLE public.hr_payroll_work_drafts IS 'Separate source-checked draft workspace; saved payroll remains immutable. Existing payroll approval/accrual remains the only posting path.';